head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataMap > P > useNull]<br/> Key 에 설정할 수 있는 값(Value)으로 null 값을 허용할지 설정합니다.",
    "validation" : [
        "''(Empty String)은 값이 있는 것으로 처리됩니다.",
        "미설정 또는 false 설정 시 Key 에 null 값을 설정할 수 없습니다.",
        "true 설정 시 Key 에 null 값을 설정할 수 있습니다.",
        "useNull=true 일때 null 값과 ''(Empty String)은 다른 값으로 처리됩니다.",
        "Key 에 null 값이 설정되어도 DataMap 모듈과 바인드 된 컴포넌트에는 ''(Empty String)으로 표시됩니다.",
        "바인드 된 컴포넌트에서 값을 변경한 경우 null 값이 수정되며 Key 의 '변경여부' 상태값도 변경됩니다.",
        "useNull=true 인 경우 Key 에 설정된 값(Value)이 null 이면 defaultValue 속성값이 적용되지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof input1 !== 'undefined') {
        input1.remove();
    }

    if (typeof input2 !== 'undefined') {
        input2.remove();
    }    

    if (typeof input3 !== 'undefined') {
        input3.remove();
    }    

    // 조건 설정       
    let properties = {
        useNull: con_useNull.getText(),
        defaultValue: "D_defaultValue",
    };    

    let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);

    $c.gcm.createLabel('label="useNull 설정 후 set 버튼 클릭 시 input1=emptystring, input2=null, input3=값 미설정 됨"', '', 'label1');       

    // target 생성
    let grp_comp = document.querySelector('.tc_group_basic');
    let strTarget = '';
    let strInput = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:dataMap ' + strNameSpace + ' ' + cList + ' id="target1" baseNode="map">';        
    strTarget += '<w2:keyInfo>';
    strTarget += '<w2:key id="key1" name="name1"></w2:key>';     
    strTarget += '<w2:key id="key2" name="name2"></w2:key>';     
    strTarget += '<w2:key id="key3" name="name3"></w2:key>';     
    strTarget += '</w2:keyInfo>';
    strTarget += '<w2:data use="true">';
    strTarget += '<key1><![CDATA[]]></key1>';
    strTarget += '<key2><![CDATA[]]></key2>';
    strTarget += '<key3><![CDATA[]]></key3>';
    strTarget += '</w2:data>';
    strTarget += '</w2:dataMap>';       

    $p.data.create(strTarget);

	// input 생성    
    $c.gcm.createEmptyInput('ref="data:target1.key1" style="width:200px; display:block;"', '', 'input1');    
    $c.gcm.createEmptyInput('ref="data:target1.key2" style="width:200px; display:block;"', '', 'input2');
    $c.gcm.createEmptyInput('ref="data:target1.key3" style="width:200px;"', '', 'input3');

    // scwin.btn_getJSON_onclick();
}



scwin.btn_getJSON_onclick = function (e) {
    let rtn = target1.getJSON();
    let jsonString = JSON.stringify(rtn);

	wf_body_bottom.getObj("scwin").setReturnValue("result.json: " + jsonString);    
    wf_body_bottom.getObj("scwin").setReturnValue("input1 value: " + input1.getValue());
    wf_body_bottom.getObj("scwin").setReturnValue("input2 value: " + input2.getValue());
    wf_body_bottom.getObj("scwin").setReturnValue("input3 value: " + input3.getValue());
};



scwin.btn_getModifiedJSON_onclick = function (e) {
    let rtn = target1.getModifiedJSON();
    let jsonString = JSON.stringify(rtn);

    wf_body_bottom.getObj("scwin").setReturnValue("getModifiedJSON : " + jsonString);  
}



scwin.btn_set_onclick = function (e) {
	target1.set("key1", "");
    target1.set("key2", null);
    target1.set("key3");

    scwin.btn_getJSON_onclick();
};
